export type TdAttributes = {
  readonly tdAttributes: Uint8Array;
  readonly mrServiceTd: Uint8Array | undefined;
};

/** dcap-qvl's `validate_attrs`, with debug and service TDs refused as well. */
export function tdAttributeFailures(report: TdAttributes): string[] {
  const [tud = 0, sec1 = 0, sec2 = 0, sec3 = 0, other4 = 0, other5 = 0, other6 = 0, other7 = 0] =
    report.tdAttributes;
  const failures: string[] = [];
  if (tud & 0x01) failures.push("debug mode is enabled");
  if (tud & ~0x01) failures.push("reserved TUD bits are set");
  if (sec1 || sec2 || sec3 & 0x0f || sec3 & 0x20) failures.push("reserved SEC bits are set");
  if (other4 || other5 || other6 || other7 & 0x7f) failures.push("reserved OTHER bits are set");
  if (!(sec3 & 0x10)) failures.push("SEPT_VE_DISABLE is not set");
  if (report.mrServiceTd?.some((byte) => byte !== 0)) failures.push("a service TD is bound");
  return failures;
}
